/**
 * A sorted list of scores that counts how many items you look at.
 * Used by problem 7. Do NOT edit this file.
 *
 * You can use:   size()   and   get(i)
 */
public class SortedScores {
    private final int[] data;     // used for small lists
    private final int generated;  // used for the huge test (0, 2, 4, ...)
    private int looks = 0;

    public SortedScores(int[] data) {
        this.data = data;
        this.generated = -1;
    }

    private SortedScores(int generatedSize) {
        this.data = null;
        this.generated = generatedSize;
    }

    /** A huge sorted list 0, 2, 4, 6, ... with n items (no memory needed). */
    public static SortedScores evens(int n) {
        return new SortedScores(n);
    }

    public int size() {
        return data != null ? data.length : generated;
    }

    public int get(int i) {
        if (i < 0 || i >= size()) {
            throw new IndexOutOfBoundsException("Index " + i + " is out of range");
        }
        looks++;
        return data != null ? data[i] : i * 2;
    }

    /** For the checker: how many items were looked at. */
    public int getLooks() {
        return looks;
    }
}
